import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { CommonModule,} from '@angular/common';
import { BillService } from '../../services/bill-service';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { UserService } from '../../services/user-service';
 import { UserDto } from '../../models/user';

@Component({
  selector: 'app-users',
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './users.html',
  styleUrl: './users.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class Users {
  Users: UserDto[] = [];
  searchTerm = '';

  constructor(private userService: UserService,  private cd: ChangeDetectorRef) {}

  ngOnInit() {
    this.userService.getUsers().subscribe(data => {
      this.Users = data;
      this.cd.markForCheck();
      console.log("Users from backend:", data);
    });

  }

  filteredUsers() {
    const term = this.searchTerm.toLowerCase();
    return this.Users.filter(u =>
      u.role.toLowerCase().includes(term) ||
      u.fullName.toLowerCase().includes(term) ||
      u.phone.toLowerCase().includes(term) ||
      u.email.toLowerCase().includes(term) 
    );
  }
  handleStatus(userId: number, action: 'accept' | 'reject' | 'deactivate') {
    console.log(`User ${userId} - Action: ${action}`);

    let newStatus: string;
    if (action === 'accept') newStatus = 'Active';
    else if (action === 'reject') newStatus = 'Rejected';
    else if (action === 'deactivate') newStatus = 'Inactive';
    else return;

    this.userService.updateUserStatus(userId, newStatus).subscribe({
      next: (updatedUser) => {
        const userIndex = this.Users.findIndex(u => u.id === userId);
        if (userIndex !== -1) {
          this.Users[userIndex] = updatedUser;
          this.cd.markForCheck();
        }
        console.log('User status updated successfully');
         this.userService.getUsers().subscribe({
      next: (freshData) => {
        this.Users = freshData;
        this.cd.markForCheck();
      }
    });
      },
      error: (error) => {
        console.error('Error updating user status:', error);
        alert('Failed to update user status. Please try again.');
      }
    });
  }

}
